.orb-1 {
  width: 520px; height: 520px;
  background: radial-gradient(circle, #6b3a1f, transparent 70%);
  top: -120px; right: -100px;
}
.orb-2 {
  width: 420px; height: 420px;
  background: radial-gradient(circle, #2a1a4a, transparent 70%);
  bottom: -100px; left: -80px;
}
.grain {
  position: absolute; inset: 0;
  background-image: radial-gradient(rgba(255,255,255,0.025) 1px, transparent 1px);
  background-size: 3px 3px;
  mix-blend-mode: overlay;
  opacity: 0.6;
}
.hero-grid {
  display: grid;
  grid-template-columns: 1.15fr 0.85fr;
  gap: 60px;
  align-items: center;
}
.hero-copy .lede {
  font-size: 17px;
  color: var(--text-dim);
  max-width: 480px;
  margin: 0 0 32px;
}
.cta-row { display: flex; gap: 12px; flex-wrap: wrap; }
.stats {
  list-style: none;
  padding: 0;
  margin: 56px 0 0;
  display: flex;
  gap: 36px;
  flex-wrap: wrap;
  border-top: 1px solid var(--line-2);
  padding-top: 28px;
}
.stats li { display: flex; flex-direction: column; gap: 2px; }
.stats strong {
  font-family: 'Fraunces', serif;
  font-size: 22px;
  color: var(--text);
  font-weight: 600;
}
.stats span { font-size: 12px; color: var(--text-mute); }

.hero-card {
  display: flex;
  flex-direction: column;
  background: var(--bg-elev);
  border: 1px solid var(--line-2);
  border-radius: var(--radius-lg);
  padding: 18px;
  box-shadow: var(--shadow);
  transform: rotate(0.5deg);
}
.hero-image {
  position: relative;
  aspect-ratio: 4/5;
  border-radius: 14px;
  overflow: hidden;
  background:
    radial-gradient(ellipse at 50% 30%, #2a2030 0%, #0e0e12 70%),
    linear-gradient(135deg, #1a1620, #0a0a0c);
}
.hero-image-inner {
  position: absolute;
  inset: 0;
  display: flex;
  align-items: flex-end;
  justify-content: center;
}
.silhouette {
  width: 60%;
  height: 80%;
  background:
    linear-gradient(180deg,
      transparent 0%,
      rgba(232,195,154,0.05) 20%,
      rgba(70,55,45,0.6) 35%,
      #1a140f 55%,
      #0d0a08 100%);
  clip-path: polygon(
    35% 0%, 65% 0%, 70% 12%, 78% 22%,
    72% 35%, 75% 55%, 80% 80%, 85% 100%,
    15% 100%, 20% 80%, 25% 55%, 28% 35%,
    22% 22%, 30% 12%
  );
  filter: blur(0.4px);
}
.badge {
  position: absolute;
  top: 14px; left: 14px;
  background: rgba(10,10,12,0.7);
  backdrop-filter: blur(8px);
  border: 1px solid var(--line);
  padding: 6px 12px;
  border-radius: 999px;
  font-size: 11px;
  letter-spacing: 0.1em;
  text-transform: uppercase;
  color: var(--accent);
}
.hero-meta {
  display: flex;
  justify-content: space-between;
  align-items: flex-end;
  padding: 18px 8px 6px;
}
.hero-meta-name {
  font-family: 'Fraunces', serif;
  font-size: 19px;
  font-weight: 600;
}
.hero-meta-sub { color: var(--text-mute); font-size: 13px; margin-top: 2px; }
.hero-meta-price {
  font-family: 'Fraunces', serif;
  font-size: 22px;
  color: var(--accent);
}

/* ===== Marquee ===== */
.marquee {
  border-block: 1px solid var(--line-2);
  background: linear-gradient(180deg, #0c0c10, #0a0a0c);
  overflow: hidden;
  padding: 22px 0;
}
.marquee-track {
  display: flex;
  gap: 36px;
  white-space: nowrap;
  font-family: 'Fraunces', serif;
  font-size: clamp(28px, 4vw, 48px);
  color: var(--text-mute);
  font-weight: 600;
  letter-spacing: -0.01em;
  width: max-content;
  animation: scroll 35s linear infinite;
}
.marquee-track span:nth-child(odd) { transition: color 0.3s; }
.marquee-track:hover span:nth-child(odd) { color: var(--accent); }

/* ===== Sections ===== */
.section { padding: 100px 0; }
.section-head {
  display: flex;
  justify-content: space-between;
  align-items: flex-end;
  flex-wrap: wrap;
  gap: 24px;
  margin-bottom: 48px;
}
.link-arrow {
  font-size: 13px;
  font-weight: 600;
  letter-spacing: 0.04em;
  color: var(--accent);
  border-bottom: 1px solid transparent;
  transition: border-color 0.2s;
  padding-bottom: 2px;
}
.link-arrow:hover { border-color: var(--accent); }
.link-arrow.small { font-size: 12px; display: inline-block; margin-top: 14px; }

.filters { display: flex; gap: 8px; flex-wrap: wrap; }
.chip {
  background: transparent;
  border: 1px solid var(--line);
  color: var(--text-dim);
  padding: 8px 16px;
  border-radius: 999px;
  font-size: 12px;
  letter-spacing: 0.02em;
  font-weight: 500;
  transition: all 0.2s;
}
.chip:hover { color: var(--text); border-color: var(--text-mute); }
.chip.is-active {
  background: var(--text);
  color: #0a0a0c;
  border-color: var(--text);
}

/* ===== Product grid ===== */
.product-grid {
  display: grid;
  grid-template-columns: repeat(4, 1fr);
  gap: 24px;
}
.product {
  display: flex;
  flex-direction: column;
  cursor: pointer;
  position: relative;
}
.product-img {
  aspect-ratio: 4/5;
  border-radius: var(--radius);
  overflow: hidden;
  position: relative;
  background: var(--bg-elev);
  border: 1px solid var(--line-2);
  transition: transform 0.4s cubic-bezier(.2,.8,.2,1), border-color 0.3s;
}
.product:hover .product-img {
  transform: translateY(-4px);
  border-color: var(--line);
}
.product-img::after {
  content: "";
  position: absolute; inset: 0;
  background: radial-gradient(ellipse at 50% 30%, rgba(255,255,255,0.05), transparent 60%);
  pointer-events: none;
}
.product-art {
  position: absolute;
  inset: 0;
  display: grid;
  place-items: center;
}
.tag-row {
  position: absolute;
  top: 12px; left: 12px;
  display: flex; gap: 6px;
}
.tag-pill {
  background: rgba(10,10,12,0.75);
  backdrop-filter: blur(6px);
  border: 1px solid var(--line);
  padding: 5px 10px;
  border-radius: 999px;
  font-size: 10px;
  letter-spacing: 0.1em;
  text-transform: uppercase;
  font-weight: 600;
}
.tag-pill.new { color: var(--accent); border-color: rgba(232,195,154,0.3); }
.tag-pill.sale { color: #ff9b7a; border-color: rgba(255,155,122,0.3); }

.add-btn {
  position: absolute;
  bottom: 12px; right: 12px;
  width: 40px; height: 40px;
  border-radius: 50%;
  background: var(--text);
  color: #0a0a0c;
  border: none;
  font-size: 22px;
  display: flex; align-items: center; justify-content: center;
  opacity: 0;
  transform: translateY(8px);
  transition: all 0.3s ease;
  font-weight: 300;
  line-height: 1;
}
.product:hover .add-btn { opacity: 1; transform: translateY(0); }
.add-btn:hover { background: var(--accent); }

.product-info {
  padding: 16px 4px 0;
  display: flex;
  justify-content: space-between;
  gap: 12px;
}
.product-name {
  font-family: 'Fraunces', serif;
  font-size: 16px;
  margin: 0 0 4px;
  font-weight: 600;
}
.product-cat { font-size: 12px; color: var(--text-mute); }
.product-price { font-family: 'Fraunces', serif; font-size: 16px; color: var(--text); white-space: nowrap; }
.product-price .was { color: var(--text-mute); text-decoration: line-through; font-size: 13px; margin-right: 6px; }
.product-price .now { color: var(--accent); }

/* product art variations (CSS-only "imagery") */
.art-coat { background:
  radial-gradient(circle at 50% 28%, #8a6a4a 0 8%, transparent 9%),
  linear-gradient(180deg, #2a2018 0%, #14100c 100%);
}
.art-coat::before { content: ""; position: absolute; bottom: 0; left: 50%; transform: translateX(-50%);
  width: 55%; height: 70%;
  background: linear-gradient(180deg, #4a3826, #1a1208);
  clip-path: polygon(20% 0, 80% 0, 95% 30%, 90% 100%, 10% 100%, 5% 30%);
}
.art-knit { background:
  repeating-linear-gradient(45deg, #2a221a 0 8px, #1d1812 8px 16px),
  #16110c;
}
.art-knit::before { content: ""; position: absolute; inset: 18% 22%;
  background: radial-gradient(circle, #3a2c20, #1a140e); border-radius: 50% 50% 30% 30%;
}
.art-shoe { background:
  radial-gradient(ellipse at 50% 60%, #1a1a20 0 35%, transparent 36%),
  linear-gradient(180deg, #14141a, #0a0a10);
}
.art-shoe::before { content: ""; position: absolute; bottom: 30%; left: 15%; right: 15%; height: 25%;
  background: linear-gradient(180deg, #2c2c34, #0a0a10);
  border-radius: 60% 40% 20% 20% / 80% 60% 20% 20%;
  box-shadow: 0 6px 0 #060608;
}
.art-bag { background: linear-gradient(180deg, #1a1410, #0a0806); }
.art-bag::before { content: ""; position: absolute; inset: 25% 22% 20%;
  background: linear-gradient(180deg, #6a4a2e, #2a1a0e);
  border-radius: 6px;
  box-shadow: inset 0 0 30px rgba(0,0,0,0.5);
}
.art-bag::after { content: ""; position: absolute; top: 18%; left: 38%; right: 38%; height: 12%;
  border: 2px solid #6a4a2e; border-bottom: none; border-radius: 50% 50% 0 0;
}
.art-trousers { background: linear-gradient(180deg, #1c1c22, #0c0c12); }
.art-trousers::before { content: ""; position: absolute; top: 15%; bottom: 5%; left: 30%; right: 30%;
  background: linear-gradient(180deg, #2a2a32 0%, #14141a 100%);
  clip-path: polygon(0 0, 100% 0, 95% 100%, 55% 100%, 50% 35%, 45% 100%, 5% 100%);
}
.art-shirt { background: linear-gradient(180deg, #181820, #0a0a10); }
.art-shirt::before { content: ""; position: absolute; top: 15%; bottom: 8%; left: 18%; right: 18%;
  background: linear-gradient(180deg, #2a2a34, #18181e);
  clip-path: polygon(20% 0, 40% 8%, 50% 4%, 60% 8%, 80% 0, 100% 25%, 95% 100%, 5% 100%, 0 25%);
}
.art-watch { background: radial-gradient(circle, #1a1a22 0 20%, #0c0c12 70%); }
.art-watch::before { content: ""; position: absolute; top: 50%; left: 50%; transform: translate(-50%, -50%);
  width: 45%; aspect-ratio: 1; border-radius: 50%;
  background: radial-gradient(circle at 30% 30%, #4a4a58, #0a0a12);
  box-shadow: inset 0 0 20px rgba(232,195,154,0.15), 0 0 40px rgba(232,195,154,0.1);
}
.art-watch::after { content: ""; position: absolute; left: 50%; top: 8%; bottom: 8%; width: 22%; transform: translateX(-50%);
  background: linear-gradient(180deg, #2a221a 0%, transparent 30%, transparent 70%, #2a221a 100%);
  z-index: -1;
}

/* ===== Deals ===== */
.deals { background: linear-gradient(180deg, var(--bg) 0%, #0c0c10 100%); }
.countdown {
  font-family: 'JetBrains Mono', ui-monospace, monospace;
  color: var(--accent);
  font-weight: 600;
  margin-left: 4px;
  font-variant-numeric: tabular-nums;
}
.deals-grid {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  grid-template-rows: auto auto;
  gap: 20px;
}
.deal {
  position: relative;
  border-radius: var(--radius-lg);
  overflow: hidden;
  background: var(--bg-elev);
  border: 1px solid var(--line-2);
  min-height: 280px;
  display: flex;
  flex-direction: column;
  justify-content: flex-end;
  transition: transform 0.4s cubic-bezier(.2,.8,.2,1), border-color 0.3s;
  isolation: isolate;
}
.deal:hover { transform: translateY(-4px); border-color: var(--line); }
.deal.big { grid-row: span 2; min-height: 580px; }
.deal.wide { grid-column: span 2; min-height: 240px; }

.deal-art {
  position: absolute; inset: 0;
  z-index: -1;
  transition: transform 0.6s cubic-bezier(.2,.8,.2,1);
}
.deal:hover .deal-art { transform: scale(1.05); }
.deal-art::after {
  content: "";
  position: absolute; inset: 0;
  background: linear-gradient(180deg, transparent 30%, rgba(8,8,10,0.85) 100%);
}
.deal-art-1 {
  background:
    radial-gradient(ellipse at 30% 30%, #3a2818 0%, transparent 50%),
    radial-gradient(ellipse at 70% 70%, #1a1a2e 0%, transparent 60%),
    linear-gradient(135deg, #1c1612, #0a0a0e);
}
.deal-art-2 {
  background:
    repeating-linear-gradient(135deg, rgba(232,195,154,0.04) 0 8px, transparent 8px 16px),
    radial-gradient(ellipse at 50% 50%, #2a2418, #0e0c08);
}
.deal-art-3 {
  background:
    radial-gradient(circle at 30% 70%, #1e1e26 0%, transparent 50%),
    linear-gradient(180deg, #14141a, #08080c);
}
.deal-art-4 {
  background:
    radial-gradient(ellipse at 70% 30%, #2a1f3a 0%, transparent 60%),
    radial-gradient(ellipse at 20% 80%, #3a2818 0%, transparent 50%),
    linear-gradient(180deg, #14101a, #0a080c);
}

.deal-body { padding: 32px; position: relative; z-index: 1; }
.deal h3 {
  font-size: clamp(22px, 2.4vw, 32px);
  margin: 8px 0 6px;
  line-height: 1.1;
}
.deal.big h3 { font-size: clamp(28px, 3.4vw, 44px); }
.deal-body p { color: var(--text-dim); margin: 0; max-width: 380px; }
.discount {
  display: inline-block;
  background: var(--accent);
  color: #1a1206;
  padding: 4px 10px;
  border-radius: 6px;
  font-size: 11px;
  font-weight: 700;
  letter-spacing: 0.06em;
}
.deal-cta {
  margin-top: 18px;
  font-size: 13px;
  font-weight: 600;
  color: var(--text);
  letter-spacing: 0.04em;
}
.deal-cta span { transition: transform 0.3s; display: inline-block; margin-left: 4px; }
.deal:hover .deal-cta span { transform: translateX(6px); color: var(--accent); }

/* ===== Editorial ===== */
.editorial { background: #08080a; }
.editorial-grid {
  display: grid;
  grid-template-columns: 1.4fr 1fr 1fr;
  gap: 28px;
}
.story {
  display: flex;
  flex-direction: column;
  cursor: pointer;
}
.story.feature { grid-row: span 2; }
.story-art {
  aspect-ratio: 4/3;
  border-radius: var(--radius);
  overflow: hidden;
  position: relative;
  margin-bottom: 18px;
  border: 1px solid var(--line-2);
  transition: transform 0.4s cubic-bezier(.2,.8,.2,1);
}
.story.feature .story-art { aspect-ratio: 4/4.6; }
.story:hover .story-art { transform: translateY(-4px); }

.story-art-1 {
  background:
    radial-gradient(ellipse at 30% 40%, #5a4530 0%, transparent 50%),
    radial-gradient(ellipse at 70% 80%, #2a2018 0%, transparent 60%),
    linear-gradient(180deg, #1a1410, #08060a);
}
.story-art-2 {
  background:
    radial-gradient(ellipse at 50% 50%, #2c2424 0%, transparent 60%),
    linear-gradient(135deg, #1a1414, #0a0a0e);
}
.story-art-3 {
  background:
    radial-gradient(ellipse at 60% 40%, #3a2a4a 0%, transparent 50%),
    linear-gradient(180deg, #1a1424, #08060a);
}
.story-art-4 {
  background:
    radial-gradient(ellipse at 40% 60%, #1e3a2a 0%, transparent 50%),
    linear-gradient(180deg, #0e1a14, #06080a);
}

.story-meta {
  font-size: 11px;
  letter-spacing: 0.08em;
  text-transform: uppercase;
  color: var(--text-mute);
  margin-bottom: 10px;
  display: flex; gap: 8px; align-items: center;
}
.tag { color: var(--accent); font-weight: 600; }
.dot { color: var(--text-mute); }
.story h3 {
  font-size: 20px;
  line-height: 1.2;
  margin: 0;
  transition: color 0.2s;
}
.story.feature h3 { font-size: 32px; line-height: 1.05; }
.story:hover h3 { color: var(--accent); }
.story p { color: var(--text-dim); margin: 10px 0 0; max-width: 520px; }

/* ===== Newsletter ===== */
.newsletter {
  border-top: 1px solid var(--line-2);
  background: linear-gradient(180deg, #0a0a0c, #0c0c10);
  padding: 90px 0;
}
.news-grid {
  display: grid;
  grid-template-columns: 1.1fr 1fr;
  gap: 60px;
  align-items: center;
}
.news-form {
  display: grid;
  grid-template-columns: 1fr auto;
  gap: 10px;
  align-items: stretch;
  position: relative;
}
.news-form input {
  background: var(--bg-elev);
  border: 1px solid var(--line);
  color: var(--text);
  padding: 16px 20px;
  border-radius: 999px;
  font-size: 14px;
  font-family: inherit;
  outline: none;
  transition: border-color 0.2s;
}
.news-form input:focus { border-color: var(--accent); }
.news-msg {
  grid-column: 1 / -1;
  font-size: 12px;
  color: var(--accent);
  min-height: 16px;
  padding-left: 20px;
}

/* ===== Footer ===== */
.footer {
  background: #06060a;
  padding: 80px 0 30px;
  border-top: 1px solid var(--line-2);
}
.footer-grid {
  display: grid;
  grid-template-columns: 2fr 1fr 1fr 1fr;
  gap: 40px;
  padding-bottom: 60px;
  border-bottom: 1px solid var(--line-2);
}
.brand-lg { font-size: 28px; }
.footer-brand .muted { max-width: 320px; margin-top: 14px; }
.footer h4 {
  font-family: 'Inter', sans-serif;
  font-size: 12px;
  font-weight: 600;
  letter-spacing: 0.12em;
  text-transform: uppercase;
  color: var(--text);
  margin: 0 0 18px;
}
.footer ul { list-style: none; padding: 0; margin: 0; display: flex; flex-direction: column; gap: 10px; }
.footer ul a { color: var(--text-dim); font-size: 14px; transition: color 0.2s; }
.footer ul a:hover { color: var(--accent); }

.footer-bottom {
  padding-top: 28px;
  display: flex;
  justify-content: space-between;
  font-size: 12px;
  color: var(--text-mute);
  flex-wrap: wrap;
  gap: 14px;
}
.socials { display: flex; gap: 20px; }
.socials a:hover { color: var(--accent); }

/* ===== Toast ===== */
.toast {
  position: fixed;
  bottom: 24px; left: 50%;
  transform: translateX(-50%) translateY(20px);
  background: var(--text);
  color: #0a0a0c;
  padding: 12px 20px;
  border-radius: 999px;
  font-size: 13px;
  font-weight: 600;
  opacity: 0;
  pointer-events: none;
  transition: all 0.3s ease;
  box-shadow: 0 12px 40px rgba(0,0,0,0.5);
  z-index: 100;
}
.toast.show { opacity: 1; transform: translateX(-50%) translateY(0); }

/* ===== Responsive ===== */
@media (max-width: 1024px) {
  .product-grid { grid-template-columns: repeat(3, 1fr); }
  .deals-grid { grid-template-columns: repeat(2, 1fr); }
  .deal.big { grid-row: span 2; }
  .deal.wide { grid-column: span 2; }
  .editorial-grid { grid-template-columns: 1fr 1fr; }
  .story.feature { grid-column: span 2; grid-row: auto; }
  .hero-grid { grid-template-columns: 1fr; gap: 40px; }
  .hero-card { max-width: 480px; margin: 0 auto; }
}
@media (max-width: 720px) {
  .container { padding: 0 18px; }
  .nav-links { display: none; }
  .nav-toggle { display: inline-flex; }
  .nav { grid-template-columns: auto 1fr auto; }
  .brand { justify-self: start; margin-left: 4px; }
  .section { padding: 70px 0; }
  .section-head { align-items: flex-start; flex-direction: column; }
  .product-grid { grid-template-columns: repeat(2, 1fr); gap: 16px; }
  .deals-grid { grid-template-columns: 1fr; }
  .deal.big, .deal.wide { grid-column: auto; grid-row: auto; min-height: 320px; }
  .editorial-grid { grid-template-columns: 1fr; }
  .story.feature { grid-column: auto; }
  .footer-grid { grid-template-columns: 1fr 1fr; }
  .news-grid { grid-template-columns: 1fr; gap: 30px; }
  .news-form { grid-template-columns: 1fr; }
  .stats { gap: 20px; }
  .display { font-size: 52px; }
}
