  -webkit-font-smoothing: antialiased;
  text-rendering: optimizeLegibility;
  overflow-x: hidden;
}
a { color: inherit; text-decoration: none; }
button { font-family: inherit; cursor: pointer; }
img { max-width: 100%; display: block; }

.container { max-width: var(--maxw); margin: 0 auto; padding: 0 28px; }

.eyebrow {
  display: inline-block;
  font-size: 11px;
  letter-spacing: 0.18em;
  text-transform: uppercase;
  color: var(--accent);
  margin-bottom: 14px;
  font-weight: 600;
}
.muted { color: var(--text-dim); }

h1, h2, h3, h4 {
  font-family: 'Fraunces', 'Times New Roman', serif;
  font-weight: 600;
  letter-spacing: -0.01em;
  margin: 0;
  color: var(--text);
}
.section-title {
  font-size: clamp(28px, 3.4vw, 44px);
  line-height: 1.05;
  margin: 4px 0 0;
}
.display {
  font-size: clamp(44px, 7.2vw, 96px);
  line-height: 0.98;
  letter-spacing: -0.025em;
  margin: 14px 0 22px;
  font-weight: 600;
}
.grad {
  background: linear-gradient(110deg, var(--accent) 10%, #f5e0c4 50%, var(--accent-2) 90%);
  -webkit-background-clip: text;
  background-clip: text;
  color: transparent;
  font-style: italic;
}

/* ===== Announce ===== */
.announce {
  background: #050507;
  color: var(--text-dim);
  font-size: 12px;
  letter-spacing: 0.06em;
  border-bottom: 1px solid var(--line-2);
  overflow: hidden;
}
.announce-track {
  display: flex;
  gap: 32px;
  padding: 10px 0;
  white-space: nowrap;
  animation: scroll 38s linear infinite;
  width: max-content;
}
.announce em { color: var(--accent); font-style: normal; font-weight: 600; }
@keyframes scroll {
  to { transform: translateX(-50%); }
}

/* ===== Header ===== */
.header {
  position: sticky;
  top: 0;
  z-index: 50;
  background: rgba(10,10,12,0.78);
  backdrop-filter: saturate(140%) blur(14px);
  -webkit-backdrop-filter: saturate(140%) blur(14px);
  border-bottom: 1px solid var(--line-2);
}
.nav {
  display: grid;
  grid-template-columns: 1fr auto 1fr;
  align-items: center;
  height: 70px;
  gap: 20px;
}
.nav-links {
  display: flex;
  gap: 28px;
  font-size: 13px;
  font-weight: 500;
  letter-spacing: 0.02em;
}
.nav-links a {
  color: var(--text-dim);
  transition: color 0.2s ease;
  position: relative;
  padding: 6px 0;
}
.nav-links a:hover { color: var(--text); }
.nav-links a.accent { color: var(--accent); }
.brand {
  font-family: 'Fraunces', serif;
  font-size: 22px;
  font-weight: 600;
  letter-spacing: 0.18em;
  display: inline-flex;
  align-items: center;
  gap: 8px;
  justify-self: center;
}
.brand-mark {
  color: var(--accent);
  font-size: 22px;
}
.nav-actions { display: flex; gap: 6px; justify-self: end; align-items: center; }
.icon-btn {
  background: transparent;
  border: none;
  color: var(--text-dim);
  width: 38px; height: 38px;
  border-radius: 50%;
  display: inline-flex;
  align-items: center; justify-content: center;
  transition: background 0.2s, color 0.2s;
  position: relative;
}
.icon-btn:hover { color: var(--text); background: var(--bg-elev); }
.cart-count {
  position: absolute;
  top: 4px; right: 4px;
  background: var(--accent);
  color: #1a1206;
  font-size: 10px;
  font-weight: 700;
  min-width: 16px; height: 16px;
  border-radius: 8px;
  display: flex; align-items: center; justify-content: center;
  padding: 0 4px;
}
.nav-toggle { display: none; }

/* ===== Buttons ===== */
.btn {
  display: inline-flex;
  align-items: center;
  gap: 8px;
  padding: 14px 24px;
  border-radius: 999px;
  font-size: 13px;
  font-weight: 600;
  letter-spacing: 0.04em;
  border: 1px solid transparent;
  transition: all 0.25s ease;
  cursor: pointer;
}
.btn-primary {
  background: var(--text);
  color: #0a0a0c;
}
.btn-primary:hover {
  background: var(--accent);
  transform: translateY(-1px);
}
.btn-ghost {
  background: transparent;
  border-color: var(--line);
  color: var(--text);
}
.btn-ghost:hover { border-color: var(--accent); color: var(--accent); }

/* ===== Hero ===== */
.hero {
  position: relative;
  padding: 60px 0 100px;
  overflow: hidden;
  isolation: isolate;
}
.hero-bg {
  position: absolute;
  inset: 0;
  z-index: -1;
  pointer-events: none;
}
.orb {
  position: absolute;
  border-radius: 50%;
  filter: blur(110px);
  opacity: 0.45;
}
.orb-1 {
  width: 520px; height: 520px;
  background: radial-gradient(circle, #6b3a1f, transparent 70%);
  top: -120px; right: -100px;
}
.orb-2 {
  width: 420px; height: 420px;
  background: radial-gradient(circle, #2a1a4a, transparent 70%);
  bottom: -100px; left: -80px;
}
.grain {
  position: absolute; inset: 0;
  background-image: radial-gradient(rgba(255,255,255,0.025) 1px, transparent 1px);
  background-size: 3px 3px;
  mix-blend-mode: overlay;
  opacity: 0.6;
}
.hero-grid {
  display: grid;
  grid-template-columns: 1.15fr 0.85fr;
  gap: 60px;
  align-items: center;
}
.hero-copy .lede {
  font-size: 17px;
  color: var(--text-dim);
  max-width: 480px;
  margin: 0 0 32px;
}
.cta-row { display: flex; gap: 12px; flex-wrap: wrap; }
.stats {
  list-style: none;
  padding: 0;
  margin: 56px 0 0;
  display: flex;
  gap: 36px;
  flex-wrap: wrap;
  border-top: 1px solid var(--line-2);
  padding-top: 28px;
}
.stats li { display: flex; flex-direction: column; gap: 2px; }
.stats strong {
  font-family: 'Fraunces', serif;
  font-size: 22px;
  color: var(--text);
  font-weight: 600;
}
.stats span { font-size: 12px; color: var(--text-mute); }

.hero-card {
  display: flex;
  flex-direction: column;
  background: var(--bg-elev);
  border: 1px solid var(--line-2);
  border-radius: var(--radius-lg);
  padding: 18px;
  box-shadow: var(--shadow);
  transform: rotate(0.5deg);
}
.hero-image {
  position: relative;
  aspect-ratio: 4/5;
  border-radius: 14px;
  overflow: hidden;
  background:
    radial-gradient(ellipse at 50% 30%, #2a2030 0%, #0e0e12 70%),
    linear-gradient(135deg, #1a1620, #0a0a0c);
}
.hero-image-inner {
  position: absolute;
  inset: 0;
  display: flex;
  align-items: flex-end;
  justify-content: center;
}
.silhouette {
  width: 60%;
  height: 80%;
  background:
    linear-gradient(180deg,
      transparent 0%,
      rgba(232,195,154,0.05) 20%,
      rgba(70,55,45,0.6) 35%,
      #1a140f 55%,
      #0d0a08 100%);
  clip-path: polygon(
    35% 0%, 65% 0%, 70% 12%, 78% 22%,
    72% 35%, 75% 55%, 80% 80%, 85% 100%,
    15% 100%, 20% 80%, 25% 55%, 28% 35%,
    22% 22%, 30% 12%
  );
  filter: blur(0.4px);
}
.badge {
  position: absolute;
  top: 14px; left: 14px;
  background: rgba(10,10,12,0.7);
  backdrop-filter: blur(8px);
  border: 1px solid var(--line);
  padding: 6px 12px;
  border-radius: 999px;
  font-size: 11px;
  letter-spacing: 0.1em;
  text-transform: uppercase;
  color: var(--accent);
}
.hero-meta {
  display: flex;
  justify-content: space-between;
  align-items: flex-end;
  padding: 18px 8px 6px;
}
.hero-meta-name {
  font-family: 'Fraunces', serif;
  font-size: 19px;
  font-weight: 600;
}
.hero-meta-sub { color: var(--text-mute); font-size: 13px; margin-top: 2px; }
.hero-meta-price {
  font-family: 'Fraunces', serif;
  font-size: 22px;
  color: var(--accent);
}

/* ===== Marquee ===== */
.marquee {
  border-block: 1px solid var(--line-2);
  background: linear-gradient(180deg, #0c0c10, #0a0a0c);
  overflow: hidden;
  padding: 22px 0;
}
.marquee-track {
  display: flex;
  gap: 36px;
  white-space: nowrap;
  font-family: 'Fraunces', serif;
  font-size: clamp(28px, 4vw, 48px);
  color: var(--text-mute);
  font-weight: 600;
  letter-spacing: -0.01em;
  width: max-content;
  animation: scroll 35s linear infinite;
}
.marquee-track span:nth-child(odd) { transition: color 0.3s; }
.marquee-track:hover span:nth-child(odd) { color: var(--accent); }

/* ===== Sections ===== */
.section { padding: 100px 0; }
.section-head {
  display: flex;
  justify-content: space-between;
  align-items: flex-end;
  flex-wrap: wrap;
  gap: 24px;
  margin-bottom: 48px;
}
.link-arrow {
  font-size: 13px;
  font-weight: 600;
  letter-spacing: 0.04em;
  color: var(--accent);
  border-bottom: 1px solid transparent;
  transition: border-color 0.2s;
  padding-bottom: 2px;
}
.link-arrow:hover { border-color: var(--accent); }
.link-arrow.small { font-size: 12px; display: inline-block; margin-top: 14px; }

.filters { display: flex; gap: 8px; flex-wrap: wrap; }
.chip {
  background: transparent;
  border: 1px solid var(--line);
  color: var(--text-dim);
  padding: 8px 16px;
  border-radius: 999px;
  font-size: 12px;
  letter-spacing: 0.02em;
  font-weight: 500;
  transition: all 0.2s;
}
.chip:hover { color: var(--text); border-color: var(--text-mute); }
.chip.is-active {
  background: var(--text);
  color: #0a0a0c;
  border-color: var(--text);
}

/* ===== Product grid ===== */
.product-grid {
  display: grid;
  grid-template-columns: repeat(4, 1fr);
  gap: 24px;
}
.product {
  display: flex;
  flex-direction: column;
  cursor: pointer;
  position: relative;
}
.product-img {
  aspect-ratio: 4/5;
  border-radius: var(--radius);
  overflow: hidden;
  position: relative;
  background: var(--bg-elev);
  border: 1px solid var(--line-2);
  transition: transform 0.4s cubic-bezier(.2,.8,.2,1), border-color 0.3s;
}
.product:hover .product-img {
  transform: translateY(-4px);
  border-color: var(--line);
}
.product-img::after {
  content: "";
  position: absolute; inset: 0;
  background: radial-gradient(ellipse at 50% 30%, rgba(255,255,255,0.05), transparent 60%);
  pointer-events: none;
}
.product-art {
  position: absolute;
  inset: 0;
  display: grid;
  place-items: center;
}
.tag-row {
  position: absolute;
  top: 12px; left: 12px;
  display: flex; gap: 6px;
}
.tag-pill {
  background: rgba(10,10,12,0.75);
  backdrop-filter: blur(6px);
  border: 1px solid var(--line);
  padding: 5px 10px;
  border-radius: 999px;
  font-size: 10px;
  letter-spacing: 0.1em;
  text-transform: uppercase;
  font-weight: 600;
}
.tag-pill.new { color: var(--accent); border-color: rgba(232,195,154,0.3); }
.tag-pill.sale { color: #ff9b7a; border-color: rgba(255,155,122,0.3); }

.add-btn {
  position: absolute;
  bottom: 12px; right: 12px;
  width: 40px; height: 40px;
  border-radius: 50%;
  background: var(--text);
  color: #0a0a0c;
  border: none;
  font-size: 22px;
  display: flex; align-items: center; justify-content: center;
  opacity: 0;
  transform: translateY(8px);
  transition: all 0.3s ease;
  font-weight: 300;
  line-height: 1;
}
.product:hover .add-btn { opacity: 1; transform: translateY(0); }
.add-btn:hover { background: var(--accent); }

.product-info {
  padding: 16px 4px 0;
  display: flex;
  justify-content: space-between;
  gap: 12px;
}
.product-name {
  font-family: 'Fraunces', serif;
  font-size: 16px;
  margin: 0 0 4px;
  font-weight: 600;
}
.product-cat { font-size: 12px; color: var(--text-mute); }
.product-price { font-family: 'Fraunces', serif; font-size: 16px; color: var(--text); white-space: nowrap; }
.product-price .was { color: var(--text-mute); text-decoration: line-through; font-size: 13px; margin-right: 6px; }
.product-price .now { color: var(--accent); }

/* product art variations (CSS-only "imagery") */
