// Featured products data
const products = [
  { id: 1, name: "The Cashmere Overcoat", cat: "outerwear", category: "Outerwear", price: 1280, art: "art-coat", tag: "new" },
  { id: 2, name: "Merino Crewneck", cat: "knitwear", category: "Knitwear", price: 240, art: "art-knit" },
  { id: 3, name: "Leather Court Sneaker", cat: "footwear", category: "Footwear", price: 320, was: 420, art: "art-shoe", tag: "sale" },
  { id: 4, name: "Heritage Watch 38mm", cat: "accessories", category: "Accessories", price: 690, art: "art-watch", tag: "new" },
  { id: 5, name: "Wool Blazer", cat: "outerwear", category: "Outerwear", price: 580, art: "art-shirt" },
  { id: 6, name: "Pleated Trousers", cat: "outerwear", category: "Tailoring", price: 220, art: "art-trousers" },
  { id: 7, name: "Chunky Cardigan", cat: "knitwear", category: "Knitwear", price: 310, was: 420, art: "art-knit", tag: "sale" },
  { id: 8, name: "Leather Holdall", cat: "accessories", category: "Accessories", price: 540, art: "art-bag", tag: "new" },
];

const grid = document.getElementById('productGrid');
const filters = document.getElementById('filters');
const cartCountEl = document.getElementById('cartCount');
const toast = document.getElementById('toast');
let cartCount = 3;
let currentFilter = 'all';

function fmt(n) { return '$' + n.toLocaleString('en-US'); }

function render() {
  const items = currentFilter === 'all'
    ? products
    : products.filter(p => p.cat === currentFilter);

  grid.innerHTML = items.map(p => `
    <div class="product" data-id="${p.id}">
      <div class="product-img">
        <div class="product-art ${p.art}"></div>
        ${p.tag ? `<div class="tag-row"><span class="tag-pill ${p.tag}">${p.tag === 'new' ? 'New' : 'Sale'}</span></div>` : ''}
        <button class="add-btn" aria-label="Add ${p.name} to cart" data-add="${p.id}">+</button>
      </div>
      <div class="product-info">
        <div>
          <div class="product-name">${p.name}</div>
          <div class="product-cat">${p.category}</div>
        </div>
        <div class="product-price">
          ${p.was ? `<span class="was">${fmt(p.was)}</span><span class="now">${fmt(p.price)}</span>` : fmt(p.price)}
        </div>
      </div>
    </div>
  `).join('');
}

filters.addEventListener('click', e => {
  const btn = e.target.closest('.chip');
  if (!btn) return;
  filters.querySelectorAll('.chip').forEach(c => c.classList.remove('is-active'));
  btn.classList.add('is-active');
  currentFilter = btn.dataset.filter;
  render();
});

grid.addEventListener('click', e => {
  const addBtn = e.target.closest('[data-add]');
  if (!addBtn) return;
  e.preventDefault();
  e.stopPropagation();
  const id = +addBtn.dataset.add;
  const p = products.find(x => x.id === id);
  cartCount++;
  cartCountEl.textContent = cartCount;
  cartCountEl.animate(
    [{ transform: 'scale(1)' }, { transform: 'scale(1.4)' }, { transform: 'scale(1)' }],
    { duration: 350, easing: 'cubic-bezier(.2,.8,.2,1)' }
  );
  showToast(`Added "${p.name}" to bag`);
});

function showToast(msg) {
  toast.textContent = msg;
  toast.classList.add('show');
  clearTimeout(showToast._t);
  showToast._t = setTimeout(() => toast.classList.remove('show'), 2200);
}

// Countdown — resets daily
const cd = document.getElementById('countdown');
function tick() {
  const now = new Date();
  const end = new Date(now);
  end.setHours(24, 0, 0, 0); // midnight
  let diff = Math.max(0, end - now);
  const h = String(Math.floor(diff / 3.6e6)).padStart(2, '0');
  diff %= 3.6e6;
  const m = String(Math.floor(diff / 6e4)).padStart(2, '0');
  diff %= 6e4;
  const s = String(Math.floor(diff / 1000)).padStart(2, '0');
  cd.textContent = `${h}:${m}:${s}`;
}
tick();
setInterval(tick, 1000);

// Newsletter
const newsForm = document.getElementById('newsForm');
const newsMsg = document.getElementById('newsMsg');
newsForm.addEventListener('submit', e => {
  e.preventDefault();
  const input = newsForm.querySelector('input');
  const email = input.value.trim();
  if (!/^\S+@\S+\.\S+$/.test(email)) {
    newsMsg.style.color = '#ff9b7a';
    newsMsg.textContent = 'Please enter a valid email.';
    return;
  }
  newsMsg.style.color = '';
  newsMsg.textContent = `✓ You're in. Watch your inbox, ${email.split('@')[0]}.`;
  input.value = '';
});

// Cart button
document.getElementById('cartBtn').addEventListener('click', () => {
  showToast(`Bag contains ${cartCount} item${cartCount === 1 ? '' : 's'}`);
});

// Reveal on scroll
const io = new IntersectionObserver((entries) => {
  entries.forEach(e => {
    if (e.isIntersecting) {
      e.target.style.opacity = '1';
      e.target.style.transform = 'translateY(0)';
      io.unobserve(e.target);
    }
  });
}, { threshold: 0.1, rootMargin: '0px 0px -60px 0px' });

function observe() {
  document.querySelectorAll('.section-head, .product, .deal, .story, .hero-card').forEach(el => {
    if (el.dataset.observed) return;
    el.dataset.observed = '1';
    el.style.opacity = '0';
    el.style.transform = 'translateY(20px)';
    el.style.transition = 'opacity 0.7s ease, transform 0.7s cubic-bezier(.2,.8,.2,1)';
    io.observe(el);
  });
}

render();
observe();
// re-observe after filter renders
const _origRender = render;
window.render = function() { _origRender(); observe(); };
filters.addEventListener('click', () => setTimeout(observe, 0));

